(* [comment removed for export] *)
Section LSD.
  Variable M0 : word -> option byte.
  Variable rom : word -> option byte.
  Variable ra : word.
  Hypothesis Hret : ret_ok ra.
  Hypothesis HLOFF : rdn ASEGS M0 (0x161878 : word) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0x10)).
  Hypothesis HCNT : rdn ASEGS M0 (0x69dfe0 : word) 4%nat = Some (word_to_le_bytes 4 (Z_to_bv 64 0)).
  Hypothesis Hcw : store_ok ASEGS M0 (0x69dfe0 : word) 4%nat = true.

  Definition lsd_mem : word -> option byte := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S20!1,2|600;!1,4|F29dfe0;!3'0/M0;vd!3,?01vv,@!2'A01!1+:0!2'5}4!2'10!1,4,B").

  Theorem lsd_run : forall regs, getr regs 4 = (0x69dfd0 : word) -> getr regs 1 = ra ->
