Lemma rd_keep : forall (M M' : word -> option byte) (a : word) (k : nat) bs, (bv_unsigned a + Z.of_nat k <= 2 ^ 64)%Z ->
  (forall x : word, (bv_unsigned a <= bv_unsigned x < bv_unsigned a + Z.of_nat k)%Z -> M' x = M x) -> rdn ASEGS M a k = Some bs -> rdn ASEGS M' a k = Some bs.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S<0|600;!1,20!1+:1|30;!1+:!1,23!1+N4%~R25!1+^94|10;!2'81#5!2'81#1!1+N7$M;R6$M';R6$a;R2$k;R+O$bs;R7$Hw;R!2'Q!2'S!2'81#3!1'T#2!2'W!1,48!1,40$E;R%x;R2%~R!2+F!2'Q9:!2'^5:!2'S9!1'T#4!3+95!1#7#2!1#8#2$R;R!3+9;!4'_0'H#7#5#4!2,_17#3!6'6;!4'_0'H#8#6#5$o;R;!3+9;!4'_0'H#8#7#6#1!7'_2'H#5#7#8#6#3#2!2,_17#4#1").
Qed.

(* [comment removed for export] *)
Section ICPT.
  Variable M0 : word -> option byte.
  Variable rom : word -> option byte.
  Variables sp ra : word.
  Variables s f arg n : Z.
  Hypothesis Hs_def : bv_unsigned sp = s.
  Hypothesis Hret : ret_ok ra.
  Hypothesis Hs : (0x1000000 <= s - 96)%Z /\ (s < 2 ^ 64)%Z.
  Hypothesis Hok : store_ok ASEGS M0 (Z_to_bv 64 (s - 96)) 96%nat = true.
  Hypothesis Hn : (0 < n)%Z /\ (n + 1 < 32)%Z.
  Hypothesis Hf : (0 <= f < 2 ^ 64)%Z.
  Hypothesis Harg : (0 <= arg < 2 ^ 64)%Z.
  Hypothesis HINIT : rdn ASEGS M0 (0x16abd8 : word) 1%nat = Some [Z_to_bv 8 1].
  Hypothesis HLOFF : rdn ASEGS M0 (0x161878 : word) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0x10)).
  Hypothesis HCNT : rdn ASEGS M0 (0x69dfe0 : word) 4%nat = Some (word_to_le_bytes 4 (Z_to_bv 64 0)).
  Hypothesis Hcw : store_ok ASEGS M0 (0x69dfe0 : word) 4%nat = true.
  Hypothesis HREAL : rdn ASEGS M0 (0x162bf0 : word) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0x141834)).
  Hypothesis HNL : rdn ASEGS M0 (0x6be263 : word) 1%nat = Some [Z_to_bv 8 0].
  Hypothesis HFIN : rdn ASEGS M0 (0x6be020 : word) 1%nat = Some [Z_to_bv 8 0].
  Hypothesis HHEAD : rdn ASEGS M0 (0x6be030 : word) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 (0x6be020 + 24))).
  Hypothesis HSLOT : rdn ASEGS M0 (0x6be028 : word) 4%nat = Some (word_to_le_bytes 4 (Z_to_bv 64 n)).
  Hypothesis HLOCKW : rdn ASEGS M0 (0x6be024 : word) 4%nat = Some (word_to_le_bytes 4 (Z_to_bv 64 0)).
  Hypothesis HWTAB : forall d (m : nat), (0 <= d)%Z -> (d + Z.of_nat m <= 544)%Z -> store_ok ASEGS M0 (Z_to_bv 64 (0x6be020 + d)) m = true.

  (* [comment removed for export] *)
  Definition cxi_fp (z : Z) : Prop :=
    (s - 96 <= z < s)%Z \/ (0x69dfe0 <= z < 0x69dfe4)%Z \/ (0x6be020 + 8 <= z < 0x6be020 + 12)%Z
    \/ (0x6be020 + 32 + 8 * n <= z < 0x6be020 + 48 + 8 * n)%Z \/ (0x6be020 + 288 + 8 * n <= z < 0x6be020 + 304 + 8 * n)%Z.

  Lemma sp_cxi : sp = Z_to_bv 64 s.  Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S30!1,2|600;!2'80/sp;!1+:0!6'6+71$s;R+7!3+92/sp;!2'10#1!4';2!2'101/sp;!2'<0/sp;/s;/Hs_def;").
Qed.

