      /\ rdn ASEGS M1 (Z_to_bv 64 (0x6be020 + 32 + 8 * n)) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 f))
      /\ rdn ASEGS M1 (Z_to_bv 64 (0x6be020 + 288 + 8 * n)) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 arg))
      /\ rdn ASEGS M1 (Z_to_bv 64 (0x6be020 + 32 + 8 * (n + 1))) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0x76048))
      /\ rdn ASEGS M1 (Z_to_bv 64 (0x6be020 + 288 + 8 * (n + 1))) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0))
      /\ rdn ASEGS M1 (Z_to_bv 64 (0x6be020 + 8)) 4%nat = Some (word_to_le_bytes 4 (Z_to_bv 64 (n + 2)))
      /\ rdn ASEGS M1 (0x69dfe0 : word) 4%nat = Some (word_to_le_bytes 4 (Z_to_bv 64 0))
